import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long modPow(long base, long exp, long mod) {
        long res = 1;
        for (long i = 0; i < exp; i++) {
            res = (res * base) % mod;
        }
        return res;
    }

    static long computePower(long base, long exp) {
        long res = 1;
        for (long i = 0; i < exp; i++) {
            res = (res * base) % MOD;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k % p == 1) {
            System.out.println(computePower(p, p));
            sc.close();
            return;
        }
        if (k % p == 0) {
            System.out.println(computePower(p, p - 1));
            sc.close();
            return;
        }
        long a = 1;
        while (true) {
            if ((p - 1) % a != 0) {
                a++;
                continue;
            }
            if (modPow(k, a, p) == 1) {
                break;
            } else {
                a++;
            }
        }
        System.out.println(computePower(p, (p - 1) / a));
        sc.close();
    }
}
